/// Execution unit.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Unit {
    /// vector ALU
    Valu,
    /// transcendental unit
    Trans,
    /// scalar ALU
    Salu,
    /// scalar memory
    Smem,
    /// vector memory (global, buffer, scratch)
    Vmem,
    /// local data share
    Lds,
    /// branch
    Branch,
    /// program control: waits, barriers, priority, end
    Ctrl,
    /// pseudo instruction, expanded or dropped before encoding
    Pseudo,
}

/// Execution unit of an opcode (`Pseudo` without a gfx950 row).
#[inline]
pub fn unit(op: Opc) -> Unit {
    match op {
        Opc::SMovB32 | Opc::SMovB64 | Opc::SNotB32 | Opc::SNotB64 | Opc::SAndSaveexecB64 | Opc::SAddU32
        | Opc::SSubU32 | Opc::SAddI32 | Opc::SSubI32 | Opc::SAddcU32 | Opc::SSubbU32 | Opc::SLshlB32
        | Opc::SLshlB64 | Opc::SLshrB32 | Opc::SLshrB64 | Opc::SAshrI32 | Opc::SAshrI64 | Opc::SLshl1AddU32
        | Opc::SLshl2AddU32 | Opc::SLshl3AddU32 | Opc::SLshl4AddU32 | Opc::SMinI32 | Opc::SMinU32 | Opc::SMaxI32
        | Opc::SMaxU32 | Opc::SAndB32 | Opc::SAndB64 | Opc::SOrB32 | Opc::SOrB64 | Opc::SXorB32 | Opc::SXorB64
        | Opc::SAndNot1B32 | Opc::SAndNot1B64 | Opc::SOrNot1B32 | Opc::SOrNot1B64 | Opc::SBfeU32 | Opc::SMulI32
        | Opc::SMulHiU32 | Opc::SMulHiI32 | Opc::SCselectB32 | Opc::SCselectB64 | Opc::SCmpEqI32
        | Opc::SCmpLgI32 | Opc::SCmpGtI32 | Opc::SCmpGeI32 | Opc::SCmpLtI32 | Opc::SCmpLeI32 | Opc::SCmpEqU32
        | Opc::SCmpLgU32 | Opc::SCmpGtU32 | Opc::SCmpGeU32 | Opc::SCmpLtU32 | Opc::SCmpLeU32 | Opc::SCmpEqU64
        | Opc::SCmpLgU64 | Opc::SMovkI32 | Opc::Gfx9(Gfx9Op::SBcnt1I32B64) | Opc::Gfx9(Gfx9Op::SFf1I32B64)
        | Opc::Gfx9(Gfx9Op::SGetregB32) | Opc::Gfx9(Gfx9Op::SFf1I32B32) => Unit::Salu,
        Opc::SNop | Opc::SWaitcnt | Opc::SEndpgm | Opc::SSendmsg | Opc::SBarrier | Opc::SBarrierLds
        | Opc::SBarrierBare | Opc::SSetprio | Opc::SWaitcntExplicit | Opc::Gfx9(Gfx9Op::SSleep) => Unit::Ctrl,
        Opc::SBranch | Opc::SCbranchScc0 | Opc::SCbranchScc1 | Opc::SCbranchExecz | Opc::SCbranchExecnz => Unit::Branch,
        Opc::SLoadB32 | Opc::SLoadB64 | Opc::SLoadB128 | Opc::SLoadB256 | Opc::SLoadB512
        | Opc::Gfx9(Gfx9Op::SMemrealtime) | Opc::Gfx9(Gfx9Op::SBufLoadB32) | Opc::Gfx9(Gfx9Op::SDcacheInv)
        | Opc::Gfx9(Gfx9Op::SMemtime) => Unit::Smem,
        Opc::VNop | Opc::VMovB32 | Opc::VReadfirstlaneB32 | Opc::VCvtF32I32 | Opc::VCvtF32U32 | Opc::VCvtU32F32
        | Opc::VCvtI32F32 | Opc::VCvtF16F32 | Opc::VCvtF32F16 | Opc::VTruncF32 | Opc::VMovB32Dpp | Opc::VNotB32
        | Opc::VRndneF32 | Opc::VCndmaskB32 | Opc::VAddF32 | Opc::VSubF32 | Opc::VSubrevF32 | Opc::VMulF32
        | Opc::VMulI32I24 | Opc::VMulU32U24 | Opc::VMulHiU32U24 | Opc::VMinF32 | Opc::VMaxF32 | Opc::VMinI32
        | Opc::VMaxI32 | Opc::VMinU32 | Opc::VMaxU32 | Opc::VLshlrevB32 | Opc::VLshrrevB32 | Opc::VAshrrevI32
        | Opc::VAndB32 | Opc::VOrB32 | Opc::VXorB32 | Opc::VAddNcU32 | Opc::VSubNcU32 | Opc::VSubrevNcU32
        | Opc::VFmacF32 | Opc::VAddCoCiU32 | Opc::VSubCoCiU32 | Opc::VMadU32U24 | Opc::VBfeU32 | Opc::VBfeI32
        | Opc::VFmaF32 | Opc::VMin3F32 | Opc::VMax3F32 | Opc::VMed3I32 | Opc::VDivFixupF32 | Opc::VDivFmasF32
        | Opc::VPermB32 | Opc::VLshlAddU32 | Opc::VAddLshlU32 | Opc::VAdd3U32 | Opc::VLshlOrB32 | Opc::VAndOrB32
        | Opc::VOr3B32 | Opc::VMbcntLoU32B32 | Opc::VMbcntHiU32B32 | Opc::VDivScaleF32 | Opc::VMadU64U32
        | Opc::VMadI64I32 | Opc::VAddCoU32 | Opc::VSubCoU32 | Opc::VSubrevCoU32 | Opc::VPackB32F16
        | Opc::VLdexpF32 | Opc::VMulLoU32 | Opc::VMulHiU32 | Opc::VMulHiI32 | Opc::VLshlrevB64
        | Opc::VLshrrevB64 | Opc::VAshrrevI64 | Opc::VReadlaneB32 | Opc::VWritelaneB32 | Opc::VFmaF64
        | Opc::VAddF64 | Opc::VMulF64 | Opc::VMaxF64 | Opc::VMinF64 | Opc::VLdexpF64 | Opc::VDivScaleF64
        | Opc::VDivFmasF64 | Opc::VDivFixupF64 | Opc::VPkFmaF16 | Opc::VPkAddF16 | Opc::VPkMulF16
        | Opc::VDot2F32F16 | Opc::VFmaMixF32 | Opc::VFmaMixloF16 | Opc::VFmaMixhiF16 | Opc::VDot2F32Bf16
        | Opc::Gfx9(Gfx9Op::VPkFmaF32) | Opc::Gfx9(Gfx9Op::VPkMulF32) | Opc::Gfx9(Gfx9Op::VPkAddF32)
        | Opc::Gfx9(Gfx9Op::VPkMovB32) | Opc::Gfx9(Gfx9Op::VMovB64) | Opc::Gfx9(Gfx9Op::VLshlAddU64)
        | Opc::Gfx9(Gfx9Op::VCvtPkF16F32) | Opc::Gfx9(Gfx9Op::VCvtPkBf16F32)
        | Opc::Gfx9(Gfx9Op::VPermlane16SwapB32) | Opc::Gfx9(Gfx9Op::VPermlane32SwapB32)
        | Opc::Gfx9(Gfx9Op::VAccvgprReadB32) | Opc::Gfx9(Gfx9Op::VAccvgprWriteB32)
        | Opc::Gfx9(Gfx9Op::VAccvgprMovB32) | Opc::Gfx9(Gfx9Op::VMfma16x16x32Bf16)
        | Opc::Gfx9(Gfx9Op::VMfma16x16x32F16) | Opc::Gfx9(Gfx9Op::VMfma16x16x16F16)
        | Opc::Gfx9(Gfx9Op::VMfma16x16x16Bf16) | Opc::Gfx9(Gfx9Op::VMfma32x32x16F16)
        | Opc::Gfx9(Gfx9Op::VMfma32x32x16Bf16) | Opc::Gfx9(Gfx9Op::VMfma32x32x8F16)
        | Opc::Gfx9(Gfx9Op::VMfma32x32x8Bf16) | Opc::Gfx9(Gfx9Op::VMfma4x4x4F16)
        | Opc::Gfx9(Gfx9Op::VMfma4x4x4Bf16) | Opc::Gfx9(Gfx9Op::VMfma16x16x32Fp8Fp8)
        | Opc::Gfx9(Gfx9Op::VMfma16x16x32Fp8Bf8) | Opc::Gfx9(Gfx9Op::VMfma16x16x32Bf8Fp8)
        | Opc::Gfx9(Gfx9Op::VMfma16x16x32Bf8Bf8) | Opc::Gfx9(Gfx9Op::VMfma16x16x128F8f6f4)
        | Opc::Gfx9(Gfx9Op::VMfma16x16x4F32) | Opc::Gfx9(Gfx9Op::VMfma32x32x2F32)
        | Opc::Gfx9(Gfx9Op::VMfma16x16x4F64) | Opc::Gfx9(Gfx9Op::VMfma4x4x4F64)
        | Opc::Gfx9(Gfx9Op::VMfmaScale32x32x64F8f6f4) | Opc::Gfx9(Gfx9Op::VCvtF32Fp8)
        | Opc::Gfx9(Gfx9Op::VCvtF32Bf8) | Opc::Gfx9(Gfx9Op::VCvtPkF32Fp8) | Opc::Gfx9(Gfx9Op::VCvtPkF32Bf8)
        | Opc::Gfx9(Gfx9Op::VCvtPkFp8F32) | Opc::Gfx9(Gfx9Op::VCvtPkBf8F32)
        | Opc::Gfx9(Gfx9Op::VCvtScalef32PkBf16Fp4) | Opc::Gfx9(Gfx9Op::VAddU32Dpp)
        | Opc::Gfx9(Gfx9Op::VCvtScalef32PkFp8F32) | Opc::Gfx9(Gfx9Op::VCvtScalef32PkBf8F32)
        | Opc::Gfx9(Gfx9Op::VMfmaScale16x16x128F8f6f4) | Opc::Gfx9(Gfx9Op::VMaximum3F32)
        | Opc::Gfx9(Gfx9Op::VBitop3B32) | Opc::Gfx9(Gfx9Op::VBfiB32) | Opc::Gfx9(Gfx9Op::VMovB32DppOld)
        | Opc::Gfx9(Gfx9Op::VMaxU32DppOld) | Opc::Gfx9(Gfx9Op::VCvtF64F32) | Opc::Gfx9(Gfx9Op::VCvtF32F64)
        | Opc::Gfx9(Gfx9Op::VBcntU32B32) | Opc::Gfx9(Gfx9Op::VAddF32Dpp) | Opc::Gfx9(Gfx9Op::VMulF32Dpp)
        | Opc::Gfx9(Gfx9Op::VMaxF32Dpp) | Opc::Gfx9(Gfx9Op::VMaxU32Dpp) => Unit::Valu,
        Opc::VExpF32 | Opc::VLogF32 | Opc::VRcpF32 | Opc::VRcpIflagF32 | Opc::VRsqF32 | Opc::VRcpF64
        | Opc::Gfx9(Gfx9Op::VRsqF64) => Unit::Trans,
        Opc::DsAddU32 | Opc::DsAddF32 | Opc::DsAddRtnU32 | Opc::DsAddRtnF32 | Opc::DsStoreB32
        | Opc::DsStore2addrB32 | Opc::DsStoreB16 | Opc::DsSwizzleB32 | Opc::DsLoadB32 | Opc::DsLoadU16
        | Opc::DsStoreB64 | Opc::DsLoadB64 | Opc::DsStoreB16D16Hi | Opc::DsLoadU16D16 | Opc::DsLoadU16D16Hi
        | Opc::DsBpermuteB32 | Opc::DsStoreB128 | Opc::DsLoadB128 | Opc::DsLoadU8 | Opc::DsStoreB8
        | Opc::DsStoreB8D16Hi | Opc::Gfx9(Gfx9Op::DsReadB64TrB16) | Opc::Gfx9(Gfx9Op::DsReadB64TrB8)
        | Opc::Gfx9(Gfx9Op::DsOrB32Raw) | Opc::Gfx9(Gfx9Op::DsWriteB32Raw) | Opc::Gfx9(Gfx9Op::DsReadB32Raw)
        | Opc::Gfx9(Gfx9Op::DsLoad2addrB32) => Unit::Lds,
        Opc::GLoadU16 | Opc::GLoadB32 | Opc::GLoadB64 | Opc::GLoadB96 | Opc::GLoadB128 | Opc::GStoreB16
        | Opc::GStoreB32 | Opc::GStoreB64 | Opc::GStoreB96 | Opc::GStoreB128 | Opc::GLoadD16B16
        | Opc::GLoadD16HiB16 | Opc::GStoreD16HiB16 | Opc::GAtomicAddU32 | Opc::GAtomicAddF32
        | Opc::ScratchLoadB32 | Opc::ScratchLoadB64 | Opc::ScratchLoadB96 | Opc::ScratchLoadB128
        | Opc::ScratchStoreB32 | Opc::ScratchStoreB64 | Opc::ScratchStoreB96 | Opc::ScratchStoreB128
        | Opc::GAtomicAddU32Rtn | Opc::GAtomicAddF32Rtn | Opc::GLoadU8 | Opc::GStoreB8 | Opc::GStoreD16HiB8
        | Opc::BufLoadB32 | Opc::BufLoadB64 | Opc::BufLoadB128 | Opc::BufStoreB16 | Opc::BufStoreB32
        | Opc::BufStoreB64 | Opc::BufStoreB128 | Opc::BufLoadU16 | Opc::BufLoadD16B16 | Opc::BufLoadD16HiB16
        | Opc::BufStoreD16HiB16 | Opc::Gfx9(Gfx9Op::BufferInv) | Opc::Gfx9(Gfx9Op::BufferWbl2)
        | Opc::Gfx9(Gfx9Op::BufLoadLdsB32) | Opc::Gfx9(Gfx9Op::BufLoadLdsB128) | Opc::Gfx9(Gfx9Op::GLoadLdsB32)
        | Opc::Gfx9(Gfx9Op::GLoadLdsB128) | Opc::Gfx9(Gfx9Op::GAtomicPkAddF16)
        | Opc::Gfx9(Gfx9Op::GAtomicPkAddF16Rtn) | Opc::Gfx9(Gfx9Op::GAtomicAddX2)
        | Opc::Gfx9(Gfx9Op::GAtomicAddX2Rtn) => Unit::Vmem,
        Opc::Copy | Opc::ImplicitDef | Opc::PackF16 | Opc::SchedBarrier | Opc::Gfx9(Gfx9Op::KeepAlive)
        | Opc::Gfx9(Gfx9Op::WaitRelease) => Unit::Pseudo,
        Opc::VCmp(_) => Unit::Valu,
        #[allow(unreachable_patterns)]
        _ => Unit::Pseudo,
    }
}

/// Whether an opcode issues to the vector ALU (VALU or transcendental).
#[inline]
pub fn is_valu(op: Opc) -> bool {
    matches!(unit(op), Unit::Valu | Unit::Trans)
}

/// Wait counters an instruction increments: vector memory loads and stores (`vmcnt`),
/// LDS and SMEM (`lgkmcnt`), SMEM alone (returns out of order).
pub const CNT_VM: u8 = 1;
pub const CNT_LGKM: u8 = 2;
pub const CNT_SMEM: u8 = 4;

/// Latency class.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Lat {
    /// pseudo without a result latency (copies, implicit defs, scheduling barriers)
    Pseudo,
    /// pseudo expanded into VALU instructions
    PseudoValu,
    /// scalar ALU
    Salu,
    /// program control (SOPP): no result
    Ctrl,
    /// vector ALU (wave64: four cycles per instruction)
    Valu,
    /// transcendental
    Trans,
    /// scalar load: lgkmcnt, returns out of order
    Smem,
    /// LDS access: lgkmcnt
    Lds,
    /// vector memory load or returning atomic: vmcnt
    VmemLoad,
    /// vector memory store or atomic without return: vmcnt
    VmemStore,
    /// cache control (buffer_inv, buffer_wbl2): no result and no counter the model ages; a fence waits for vmcnt(0) itself
    Cache,
    /// MFMA on the XDL pipe, 2 passes
    MfmaXdl2,
    /// MFMA on the XDL pipe, 4 passes
    MfmaXdl4,
    /// MFMA on the XDL pipe, 8 passes
    MfmaXdl8,
    /// MFMA on the XDL pipe, 16 passes (the block-scaled f8f6f4 form with fp8 or bf8 operands; the rules take 16 for every format)
    MfmaXdl16,
    /// MFMA off the XDL pipe (f32 inputs), 8 passes
    MfmaSmfma8,
    /// MFMA off the XDL pipe (f32 inputs), 16 passes
    MfmaSmfma16,
    /// f64 MFMA, 4x4 blocks (DGEMM)
    MfmaDgemm4,
    /// f64 MFMA, 16x16 (DGEMM)
    MfmaDgemm16,
}

impl Lat {
    /// Cycles from issue until a reader of the result may issue.
    #[inline]
    pub fn sched(self) -> u32 {
        match self {
            Lat::Pseudo => 0,
            Lat::PseudoValu => 8,
            Lat::Salu => 2,
            Lat::Ctrl => 4,
            Lat::Valu => 8,
            Lat::Trans => 16,
            Lat::Smem => 40,
            Lat::Lds => 64,
            Lat::VmemLoad => 500,
            Lat::VmemStore => 8,
            Lat::Cache => 4,
            Lat::MfmaXdl2 => 20,
            Lat::MfmaXdl4 => 32,
            Lat::MfmaXdl8 => 48,
            Lat::MfmaXdl16 => 80,
            Lat::MfmaSmfma8 => 40,
            Lat::MfmaSmfma16 => 72,
            Lat::MfmaDgemm4 => 36,
            Lat::MfmaDgemm16 => 76,
        }
    }

    /// Wait counters (`CNT_*`) the instruction increments.
    #[inline]
    pub fn counters(self) -> u8 {
        match self {
            Lat::Pseudo => 0,
            Lat::PseudoValu => 0,
            Lat::Salu => 0,
            Lat::Ctrl => 0,
            Lat::Valu => 0,
            Lat::Trans => 0,
            Lat::Smem => CNT_LGKM | CNT_SMEM,
            Lat::Lds => CNT_LGKM,
            Lat::VmemLoad => CNT_VM,
            Lat::VmemStore => CNT_VM,
            Lat::Cache => 0,
            Lat::MfmaXdl2 => 0,
            Lat::MfmaXdl4 => 0,
            Lat::MfmaXdl8 => 0,
            Lat::MfmaXdl16 => 0,
            Lat::MfmaSmfma8 => 0,
            Lat::MfmaSmfma16 => 0,
            Lat::MfmaDgemm4 => 0,
            Lat::MfmaDgemm16 => 0,
        }
    }
}

/// Latency class of an opcode (`Pseudo` without a gfx950 row).
#[inline]
pub fn lat(op: Opc) -> Lat {
    match op {
        Opc::SMovB32 | Opc::SMovB64 | Opc::SNotB32 | Opc::SNotB64 | Opc::SAndSaveexecB64 | Opc::SAddU32
        | Opc::SSubU32 | Opc::SAddI32 | Opc::SSubI32 | Opc::SAddcU32 | Opc::SSubbU32 | Opc::SLshlB32
        | Opc::SLshlB64 | Opc::SLshrB32 | Opc::SLshrB64 | Opc::SAshrI32 | Opc::SAshrI64 | Opc::SLshl1AddU32
        | Opc::SLshl2AddU32 | Opc::SLshl3AddU32 | Opc::SLshl4AddU32 | Opc::SMinI32 | Opc::SMinU32 | Opc::SMaxI32
        | Opc::SMaxU32 | Opc::SAndB32 | Opc::SAndB64 | Opc::SOrB32 | Opc::SOrB64 | Opc::SXorB32 | Opc::SXorB64
        | Opc::SAndNot1B32 | Opc::SAndNot1B64 | Opc::SOrNot1B32 | Opc::SOrNot1B64 | Opc::SBfeU32 | Opc::SMulI32
        | Opc::SMulHiU32 | Opc::SMulHiI32 | Opc::SCselectB32 | Opc::SCselectB64 | Opc::SCmpEqI32
        | Opc::SCmpLgI32 | Opc::SCmpGtI32 | Opc::SCmpGeI32 | Opc::SCmpLtI32 | Opc::SCmpLeI32 | Opc::SCmpEqU32
        | Opc::SCmpLgU32 | Opc::SCmpGtU32 | Opc::SCmpGeU32 | Opc::SCmpLtU32 | Opc::SCmpLeU32 | Opc::SCmpEqU64
        | Opc::SCmpLgU64 | Opc::SMovkI32 | Opc::Gfx9(Gfx9Op::SBcnt1I32B64) | Opc::Gfx9(Gfx9Op::SFf1I32B64)
        | Opc::Gfx9(Gfx9Op::SGetregB32) | Opc::Gfx9(Gfx9Op::SFf1I32B32) => Lat::Salu,
        Opc::SNop | Opc::SWaitcnt | Opc::SBranch | Opc::SCbranchScc0 | Opc::SCbranchScc1 | Opc::SCbranchExecz
        | Opc::SCbranchExecnz | Opc::SEndpgm | Opc::SSendmsg | Opc::SBarrier | Opc::SBarrierLds
        | Opc::SBarrierBare | Opc::SSetprio | Opc::SWaitcntExplicit | Opc::Gfx9(Gfx9Op::SSleep) => Lat::Ctrl,
        Opc::SLoadB32 | Opc::SLoadB64 | Opc::SLoadB128 | Opc::SLoadB256 | Opc::SLoadB512
        | Opc::Gfx9(Gfx9Op::SMemrealtime) | Opc::Gfx9(Gfx9Op::SBufLoadB32) | Opc::Gfx9(Gfx9Op::SDcacheInv)
        | Opc::Gfx9(Gfx9Op::SMemtime) => Lat::Smem,
        Opc::VNop | Opc::VMovB32 | Opc::VReadfirstlaneB32 | Opc::VCvtF32I32 | Opc::VCvtF32U32 | Opc::VCvtU32F32
        | Opc::VCvtI32F32 | Opc::VCvtF16F32 | Opc::VCvtF32F16 | Opc::VTruncF32 | Opc::VMovB32Dpp | Opc::VNotB32
        | Opc::VRndneF32 | Opc::VCndmaskB32 | Opc::VAddF32 | Opc::VSubF32 | Opc::VSubrevF32 | Opc::VMulF32
        | Opc::VMulI32I24 | Opc::VMulU32U24 | Opc::VMulHiU32U24 | Opc::VMinF32 | Opc::VMaxF32 | Opc::VMinI32
        | Opc::VMaxI32 | Opc::VMinU32 | Opc::VMaxU32 | Opc::VLshlrevB32 | Opc::VLshrrevB32 | Opc::VAshrrevI32
        | Opc::VAndB32 | Opc::VOrB32 | Opc::VXorB32 | Opc::VAddNcU32 | Opc::VSubNcU32 | Opc::VSubrevNcU32
        | Opc::VFmacF32 | Opc::VAddCoCiU32 | Opc::VSubCoCiU32 | Opc::VMadU32U24 | Opc::VBfeU32 | Opc::VBfeI32
        | Opc::VFmaF32 | Opc::VMin3F32 | Opc::VMax3F32 | Opc::VMed3I32 | Opc::VDivFixupF32 | Opc::VDivFmasF32
        | Opc::VPermB32 | Opc::VLshlAddU32 | Opc::VAddLshlU32 | Opc::VAdd3U32 | Opc::VLshlOrB32 | Opc::VAndOrB32
        | Opc::VOr3B32 | Opc::VMbcntLoU32B32 | Opc::VMbcntHiU32B32 | Opc::VDivScaleF32 | Opc::VMadU64U32
        | Opc::VMadI64I32 | Opc::VAddCoU32 | Opc::VSubCoU32 | Opc::VSubrevCoU32 | Opc::VPackB32F16
        | Opc::VLdexpF32 | Opc::VMulLoU32 | Opc::VMulHiU32 | Opc::VMulHiI32 | Opc::VLshlrevB64
        | Opc::VLshrrevB64 | Opc::VAshrrevI64 | Opc::VReadlaneB32 | Opc::VWritelaneB32 | Opc::VFmaF64
        | Opc::VAddF64 | Opc::VMulF64 | Opc::VMaxF64 | Opc::VMinF64 | Opc::VLdexpF64 | Opc::VDivScaleF64
        | Opc::VDivFmasF64 | Opc::VDivFixupF64 | Opc::VPkFmaF16 | Opc::VPkAddF16 | Opc::VPkMulF16
        | Opc::VDot2F32F16 | Opc::VFmaMixF32 | Opc::VFmaMixloF16 | Opc::VFmaMixhiF16 | Opc::VDot2F32Bf16
        | Opc::Gfx9(Gfx9Op::VPkFmaF32) | Opc::Gfx9(Gfx9Op::VPkMulF32) | Opc::Gfx9(Gfx9Op::VPkAddF32)
        | Opc::Gfx9(Gfx9Op::VPkMovB32) | Opc::Gfx9(Gfx9Op::VMovB64) | Opc::Gfx9(Gfx9Op::VLshlAddU64)
        | Opc::Gfx9(Gfx9Op::VCvtPkF16F32) | Opc::Gfx9(Gfx9Op::VCvtPkBf16F32)
        | Opc::Gfx9(Gfx9Op::VPermlane16SwapB32) | Opc::Gfx9(Gfx9Op::VPermlane32SwapB32)
        | Opc::Gfx9(Gfx9Op::VAccvgprReadB32) | Opc::Gfx9(Gfx9Op::VAccvgprWriteB32)
        | Opc::Gfx9(Gfx9Op::VAccvgprMovB32) | Opc::Gfx9(Gfx9Op::VCvtF32Fp8) | Opc::Gfx9(Gfx9Op::VCvtF32Bf8)
        | Opc::Gfx9(Gfx9Op::VCvtPkF32Fp8) | Opc::Gfx9(Gfx9Op::VCvtPkF32Bf8) | Opc::Gfx9(Gfx9Op::VCvtPkFp8F32)
        | Opc::Gfx9(Gfx9Op::VCvtPkBf8F32) | Opc::Gfx9(Gfx9Op::VCvtScalef32PkBf16Fp4)
        | Opc::Gfx9(Gfx9Op::VAddU32Dpp) | Opc::Gfx9(Gfx9Op::VCvtScalef32PkFp8F32)
        | Opc::Gfx9(Gfx9Op::VCvtScalef32PkBf8F32) | Opc::Gfx9(Gfx9Op::VMaximum3F32)
        | Opc::Gfx9(Gfx9Op::VBitop3B32) | Opc::Gfx9(Gfx9Op::VBfiB32) | Opc::Gfx9(Gfx9Op::VMovB32DppOld)
        | Opc::Gfx9(Gfx9Op::VMaxU32DppOld) | Opc::Gfx9(Gfx9Op::VCvtF64F32) | Opc::Gfx9(Gfx9Op::VCvtF32F64)
        | Opc::Gfx9(Gfx9Op::VBcntU32B32) | Opc::Gfx9(Gfx9Op::VAddF32Dpp) | Opc::Gfx9(Gfx9Op::VMulF32Dpp)
        | Opc::Gfx9(Gfx9Op::VMaxF32Dpp) | Opc::Gfx9(Gfx9Op::VMaxU32Dpp) => Lat::Valu,
        Opc::VExpF32 | Opc::VLogF32 | Opc::VRcpF32 | Opc::VRcpIflagF32 | Opc::VRsqF32 | Opc::VRcpF64
        | Opc::Gfx9(Gfx9Op::VRsqF64) => Lat::Trans,
        Opc::DsAddU32 | Opc::DsAddF32 | Opc::DsAddRtnU32 | Opc::DsAddRtnF32 | Opc::DsStoreB32
        | Opc::DsStore2addrB32 | Opc::DsStoreB16 | Opc::DsSwizzleB32 | Opc::DsLoadB32 | Opc::DsLoadU16
        | Opc::DsStoreB64 | Opc::DsLoadB64 | Opc::DsStoreB16D16Hi | Opc::DsLoadU16D16 | Opc::DsLoadU16D16Hi
        | Opc::DsBpermuteB32 | Opc::DsStoreB128 | Opc::DsLoadB128 | Opc::DsLoadU8 | Opc::DsStoreB8
        | Opc::DsStoreB8D16Hi | Opc::Gfx9(Gfx9Op::DsReadB64TrB16) | Opc::Gfx9(Gfx9Op::DsReadB64TrB8)
        | Opc::Gfx9(Gfx9Op::DsOrB32Raw) | Opc::Gfx9(Gfx9Op::DsWriteB32Raw) | Opc::Gfx9(Gfx9Op::DsReadB32Raw)
        | Opc::Gfx9(Gfx9Op::DsLoad2addrB32) => Lat::Lds,
        Opc::GLoadU16 | Opc::GLoadB32 | Opc::GLoadB64 | Opc::GLoadB96 | Opc::GLoadB128 | Opc::GLoadD16B16
        | Opc::GLoadD16HiB16 | Opc::ScratchLoadB32 | Opc::ScratchLoadB64 | Opc::ScratchLoadB96
        | Opc::ScratchLoadB128 | Opc::GAtomicAddU32Rtn | Opc::GAtomicAddF32Rtn | Opc::GLoadU8 | Opc::BufLoadB32
        | Opc::BufLoadB64 | Opc::BufLoadB128 | Opc::BufLoadU16 | Opc::BufLoadD16B16 | Opc::BufLoadD16HiB16
        | Opc::Gfx9(Gfx9Op::BufLoadLdsB32) | Opc::Gfx9(Gfx9Op::BufLoadLdsB128) | Opc::Gfx9(Gfx9Op::GLoadLdsB32)
        | Opc::Gfx9(Gfx9Op::GLoadLdsB128) | Opc::Gfx9(Gfx9Op::GAtomicPkAddF16Rtn)
        | Opc::Gfx9(Gfx9Op::GAtomicAddX2Rtn) => Lat::VmemLoad,
        Opc::GStoreB16 | Opc::GStoreB32 | Opc::GStoreB64 | Opc::GStoreB96 | Opc::GStoreB128
        | Opc::GStoreD16HiB16 | Opc::GAtomicAddU32 | Opc::GAtomicAddF32 | Opc::ScratchStoreB32
        | Opc::ScratchStoreB64 | Opc::ScratchStoreB96 | Opc::ScratchStoreB128 | Opc::GStoreB8
        | Opc::GStoreD16HiB8 | Opc::BufStoreB16 | Opc::BufStoreB32 | Opc::BufStoreB64 | Opc::BufStoreB128
        | Opc::BufStoreD16HiB16 | Opc::Gfx9(Gfx9Op::GAtomicPkAddF16) | Opc::Gfx9(Gfx9Op::GAtomicAddX2) => Lat::VmemStore,
        Opc::Copy | Opc::ImplicitDef | Opc::SchedBarrier | Opc::Gfx9(Gfx9Op::KeepAlive)
        | Opc::Gfx9(Gfx9Op::WaitRelease) => Lat::Pseudo,
        Opc::PackF16 => Lat::PseudoValu,
        Opc::Gfx9(Gfx9Op::BufferInv) | Opc::Gfx9(Gfx9Op::BufferWbl2) => Lat::Cache,
        Opc::Gfx9(Gfx9Op::VMfma16x16x32Bf16) | Opc::Gfx9(Gfx9Op::VMfma16x16x32F16)
        | Opc::Gfx9(Gfx9Op::VMfma16x16x16F16) | Opc::Gfx9(Gfx9Op::VMfma16x16x16Bf16)
        | Opc::Gfx9(Gfx9Op::VMfma16x16x32Fp8Fp8) | Opc::Gfx9(Gfx9Op::VMfma16x16x32Fp8Bf8)
        | Opc::Gfx9(Gfx9Op::VMfma16x16x32Bf8Fp8) | Opc::Gfx9(Gfx9Op::VMfma16x16x32Bf8Bf8) => Lat::MfmaXdl4,
        Opc::Gfx9(Gfx9Op::VMfma32x32x16F16) | Opc::Gfx9(Gfx9Op::VMfma32x32x16Bf16)
        | Opc::Gfx9(Gfx9Op::VMfma32x32x8F16) | Opc::Gfx9(Gfx9Op::VMfma32x32x8Bf16)
        | Opc::Gfx9(Gfx9Op::VMfma16x16x128F8f6f4) | Opc::Gfx9(Gfx9Op::VMfmaScale16x16x128F8f6f4) => Lat::MfmaXdl8,
        Opc::Gfx9(Gfx9Op::VMfma4x4x4F16) | Opc::Gfx9(Gfx9Op::VMfma4x4x4Bf16) => Lat::MfmaXdl2,
        Opc::Gfx9(Gfx9Op::VMfma16x16x4F32) => Lat::MfmaSmfma8,
        Opc::Gfx9(Gfx9Op::VMfma32x32x2F32) => Lat::MfmaSmfma16,
        Opc::Gfx9(Gfx9Op::VMfma16x16x4F64) => Lat::MfmaDgemm16,
        Opc::Gfx9(Gfx9Op::VMfma4x4x4F64) => Lat::MfmaDgemm4,
        Opc::Gfx9(Gfx9Op::VMfmaScale32x32x64F8f6f4) => Lat::MfmaXdl16,
        Opc::VCmp(_) => Lat::Valu,
        #[allow(unreachable_patterns)]
        _ => Lat::Pseudo,
    }
}

/// Scheduler result latency of an opcode.
#[inline]
pub fn result_latency(op: Opc) -> u32 {
    lat(op).sched()
}

/// Wait counters an opcode increments.
#[inline]
pub fn counters(op: Opc) -> u8 {
    lat(op).counters()
}

/// How the encoder treats an opcode within its format.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Form {
    /// the format's general encoding
    Plain,
    /// SALU with 64-bit integer sources: no f32 inline constants (a literal is zero-extended)
    B64,
    /// SALU 64-bit shift: source 0 as in b64, source 1 the 32-bit shift amount
    B64Shift,
    /// VOP1 with a 16-bit source: op_sel on source 0 is an SDWA word with src0_sel:WORD_1
    SdwaHi,
    /// VOP1 with a DPP source: imm holds bits 31:8 of the DPP word
    Dpp16,
    /// VALU with f64 sources: a non-inline-integer immediate is the high dword (an f64 inline constant or a literal)
    F64,
    /// a VOP2 opcode always encoded as VOP3 (its lane mask is explicit)
    Noshort,
    /// VOP3 with 16-bit sources: no f32 inline constants
    Src16,
    /// VOP3 with two encoded sources and no f32 inline constants
    Writelane,
    /// as f64, but source 1 is the 32-bit integer exponent (v_ldexp_f64)
    F64I32,
    /// VOP3P with 16-bit pair sources 0 and 1 (no f32 inline constants) and an f32 source 2
    Dot2,
    /// VOP3P taking op_sel and op_sel_hi from the modifiers
    Mix,
    /// DS with both a result and data0 (returning atomics, bpermute)
    DsData,
    /// DS with data0 and data1 (two-address store)
    Ds2addr,
    /// SCRATCH (FLAT segment 1) with no address operands: the offset is in imm
    Scratch,
    /// VOP3P on two 32-bit lanes: register sources at even registers, imm holds the lane selects, neg negates both lanes
    Pk32,
    /// VOP1 exchanging lanes of two VGPRs, both read and written: defs and uses are (vdst, vsrc)
    Swap,
    /// MUBUF cache control with no address or data: imm holds the cache policy
    Nodata,
    /// VOP3P v_accvgpr_read: src0 is an AGPR, encoded by its index
    AccRead,
    /// VOP3P v_accvgpr_write: vdst is an AGPR, encoded by its index
    AccWrite,
    /// VOP1 v_accvgpr_mov: vdst is an AGPR encoded by its index, src0 an AGPR encoded as 256 + index
    AccMov,
    /// VOP3P-MAI: AGPR vdst and src2 set acc_cd, an AGPR src0 or src1 its acc bit; imm holds the MFMA controls
    Mai,
    /// VOP3PX2: v_mfma_ld_scale_b32 reading the A and B scale VGPRs, then the MFMA as in mai (abid refused)
    MaiScale,
    /// load into LDS (MUBUF with the lds bit, GLOBAL's global_load_lds): no data register, M0 the LDS address; imm holds the offset and the cache policy
    Lds,
    /// SMEM without an address (s_memrealtime): sdata only, the imm bit clear
    Nobase,
}

/// What the encoder reads of an opcode, in one load.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Info {
    /// Opcode field of the encoding.
    pub code: u16,
    /// Opcode of the VOP3 encoding (VOP1 and VOP2 promoted, VOPC, native VOP3).
    pub vop3: u16,
    /// The shared flags (`Opc::flags`).
    pub flags: u32,
    pub fmt: Fmt,
    pub form: Form,
    /// Whether the encoder encodes the opcode (pseudos are not).
    pub table: bool,
}

