/// `Info` of an opcode, or `None` when gfx950 has no encoding for it.
#[inline]
pub fn info(op: Opc) -> Option<Info> {
    let mut info = INFO[index(op)?];
    if let Opc::VCmp(code) = op {
        let (gfx9, _) = vcmp(code)?;
        info.code = gfx9;
        info.vop3 = gfx9;
        info.flags = op.flags();
    }
    Some(info)
}

