/// Operand role: the encoding field an operand goes to.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Role {
    Sdst,
    Ssrc0,
    Exec,
    Ssrc1,
    Sdata,
    Sbase,
    Vdst,
    Src0,
    Src1,
    Src2,
    Vsrc1,
    Old,
    Addr,
    Data0,
    Data1,
    Vaddr,
    Vdata,
    Srsrc,
    Soffset,
    Dst,
    Src,
    Vsrc,
    ScaleA,
    ScaleB,
}

/// Operand class.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Class {
    /// SGPR tuple; as a 1-dword destination also vcc_lo, exec_lo or m0; a lane mask is an SGPR pair, VCC or EXEC
    S,
    /// scalar source: SGPR, special register, inline constant or literal
    Ss,
    /// EXEC, named as an explicit operand
    X,
    /// VGPR tuple
    V,
    /// vector source: VGPR, SGPR, special register, inline constant, or a literal when not VOP3-encoded
    Vs,
    /// vector source without a literal: VGPR, SGPR or inline constant
    Vi,
    /// any register (pseudo)
    A,
    /// vector source that is a register: VGPR, SGPR or special register tuple, no constant
    Vr,
    /// AGPR tuple: AGPR a<k> is Phys::V(256 + k), the AGPR half of the unified register file
    Acc,
    /// VGPR or AGPR tuple
    Av,
    /// VGPR or AGPR tuple, or an inline constant
    Avi,
}

/// What `MInst::imm` holds.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Imm {
    /// nothing
    None,
    /// 16-bit immediate field
    Simm16,
    /// wait states minus one
    Nop,
    /// gfx9 s_waitcnt: vmcnt bits 3:0 and 15:14, expcnt 6:4, lgkmcnt 11:8
    Waitcnt,
    /// branch target block (resolved to a word offset by the assembler)
    Label,
    /// message id
    Sendmsg,
    /// 21-bit signed byte offset
    Soff21,
    /// DPP control: bits 31:8 of the DPP word (gfx9 controls only; no fi bit)
    Dpp16,
    /// 16-bit unsigned byte offset
    Off16,
    /// two 8-bit dword offsets: offset0 | offset1 << 8
    Off2x8,
    /// ds_swizzle pattern
    Swizzle,
    /// 13-bit signed byte offset
    Off13s,
    /// 12-bit unsigned byte offset
    Off12,
    /// lane selects of a packed 32-bit instruction: op_sel in bits 2:0, the op_sel_hi bits cleared in 6:4 (0: each lane reads its own half)
    Pksel,
    /// cache policy: sc0 in bit 0, sc1 in bit 1
    Cpol,
    /// MFMA controls: cbsz in bits 2:0, abid in bits 6:3, blgp in bits 9:7
    Mai,
    /// 12-bit unsigned byte offset in bits 11:0, then the cache policy: sc0 in bit 12, nt in bit 13, sc1 in bit 14
    Off12cpol,
    /// v_bitop3 truth table (source bytes 0xf0, 0xcc, 0xaa): bits 2:0 in neg, 5:3 in abs, 7:6 in omod
    Bitop3,
}

/// One operand of a signature: role, class and size in dwords.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Operand {
    pub role: Role,
    pub class: Class,
    pub dwords: u8,
}

